function obterQuizSemanal() {
  const inicio = new Date(2026, 0, 5).getTime();
  const agora = new Date();
  agora.setHours(0, 0, 0, 0);
  const semanaMs = 7 * 24 * 60 * 60 * 1000;
  const indice = Math.floor((agora.getTime() - inicio) / semanaMs);
  const indiceSeguro = ((indice % QUIZZES_SEMANAIS.length) + QUIZZES_SEMANAIS.length) % QUIZZES_SEMANAIS.length;
  return QUIZZES_SEMANAIS[indiceSeguro];
}

function fotosPorUidParaNomes(fotosPorUid: Record<string, unknown>) {
  return Object.entries(fotosPorUid).reduce((acc, [uid, foto]) => {
    const nome = UID_TO_NOME[uid];
    if (nome && typeof foto === 'string') acc[nome] = foto;
    return acc;
  }, {} as Record<string, string>);
}

export default function InteracaoScreen() {
  const navigation = useNavigation();
  const [abaAtiva, setAbaAtiva] = React.useState<AbaInteracao>('oracao');
  const [novoPedido, setNovoPedido] = React.useState('');
  const [novoVersiculo, setNovoVersiculo] = React.useState('');
  const [novaReferencia, setNovaReferencia] = React.useState('');
  const [pedidos, setPedidos] = React.useState<PedidoOracao[]>([]);
  const [versiculos, setVersiculos] = React.useState<VersiculoDia[]>([]);
  const [pontos, setPontos] = React.useState<Record<string, number>>({});
  const [fotosUsuarios, setFotosUsuarios] = React.useState<Record<string, string>>(FOTOS_PADRAO);
  const [pontosAnimados, setPontosAnimados] = React.useState(0);
  const [feedbackQuiz, setFeedbackQuiz] = React.useState<'acerto' | 'erro' | null>(null);
  const [tutorialVisivel, setTutorialVisivel] = React.useState(false);
  const moedaAnim = React.useRef(new Animated.Value(0)).current;
  const feedbackAnim = React.useRef(new Animated.Value(0)).current;
  const iconPulse = React.useRef(new Animated.Value(0)).current;
  const usuarioAtual = auth.currentUser;
  const uidAtual = usuarioAtual?.uid || '';
  const nomeAtual = UID_TO_NOME[uidAtual] || usuarioAtual?.displayName || usuarioAtual?.email || 'Participante';
  const quizAtual = React.useMemo(() => obterQuizSemanal(), []);

  React.useEffect(() => {
    const animacaoIcones = Animated.loop(
      Animated.sequence([
        Animated.timing(iconPulse, {
          toValue: 1,
          duration: 1300,
          useNativeDriver: true,
        }),
        Animated.timing(iconPulse, {
          toValue: 0,
          duration: 1300,
          useNativeDriver: true,
        }),
      ])
    );
    animacaoIcones.start();

    const unsubscribePedidos = onSnapshot(
      query(collection(firestore, 'interacaoPedidos'), orderBy('criadoEm', 'desc')),
      snapshot => {
        setPedidos(snapshot.docs.map(docSnap => ({ id: docSnap.id, ...docSnap.data() } as PedidoOracao)));
      }
    );

    const unsubscribeVersiculos = onSnapshot(
      query(collection(firestore, 'interacaoVersiculos'), orderBy('criadoEm', 'desc')),
      snapshot => {
        setVersiculos(snapshot.docs.map(docSnap => ({ id: docSnap.id, ...docSnap.data() } as VersiculoDia)));
      }
    );

    const unsubscribePontos = onSnapshot(collection(firestore, 'interacaoPontos'), snapshot => {
      const pontosAtualizados: Record<string, number> = {};
      snapshot.forEach(docSnap => {
        pontosAtualizados[docSnap.id] = Number(docSnap.data().pontos || 0);
      });
      setPontos(pontosAtualizados);
    });

    const unsubscribeFotos = onSnapshot(collection(firestore, 'presencas'), snapshot => {
      const fotosBanco = snapshot.docs.reduce((acc, docSnap) => ({
        ...acc,
        ...(docSnap.data().fotosUsuarios || {}),
        ...fotosPorUidParaNomes(docSnap.data().fotosPorUid || {}),
      }), {});
      setFotosUsuarios({ ...FOTOS_PADRAO, ...fotosBanco });
    });

    return () => {
      unsubscribePedidos();
      unsubscribeVersiculos();
      unsubscribePontos();
      unsubscribeFotos();
      animacaoIcones.stop();
    };
  }, [iconPulse]);

  async function adicionarPontos(uid: string, nome: string, quantidade: number) {
    await setDoc(doc(firestore, 'interacaoPontos', uid), {
      nome,
      pontos: increment(quantidade),
      atualizadoEm: serverTimestamp(),
    }, { merge: true });
  }

  function animarMoedinha(quantidade: number) {
    setPontosAnimados(quantidade);
    moedaAnim.stopAnimation();
    moedaAnim.setValue(0);
    Animated.sequence([
      Animated.timing(moedaAnim, {
        toValue: 1,
        duration: 360,
        useNativeDriver: true,
      }),
      Animated.delay(520),
      Animated.timing(moedaAnim, {
        toValue: 2,
        duration: 420,
        useNativeDriver: true,
      }),
    ]).start();
  }

  function animarFeedbackQuiz(tipo: 'acerto' | 'erro') {
    setFeedbackQuiz(tipo);
    feedbackAnim.stopAnimation();
    feedbackAnim.setValue(0);
    Animated.sequence([
      Animated.timing(feedbackAnim, {
        toValue: 1,
        duration: 260,
        useNativeDriver: true,
      }),
      Animated.delay(760),
      Animated.timing(feedbackAnim, {
        toValue: 2,
        duration: 360,
        useNativeDriver: true,
      }),
    ]).start(({ finished }) => {
      if (finished) setFeedbackQuiz(null);
    });
  }

  async function publicarPedido() {
    if (!uidAtual) {
      Alert.alert('Atenção', 'Entre na sua conta para participar.');
      return;
    }

    const texto = novoPedido.trim();
    if (!texto) return;

    await addDoc(collection(firestore, 'interacaoPedidos'), {
      texto,
      autorUid: uidAtual,
      autorNome: nomeAtual,
      reacoes: [],
      reacoesEmoji: {},
      criadoEm: serverTimestamp(),
    });
    setNovoPedido('');
  }

  async function reagirPedido(pedido: PedidoOracao, emoji: string) {
    if (!uidAtual) {
      Alert.alert('Atenção', 'Entre na sua conta para participar.');
      return;
    }

    await updateDoc(doc(firestore, 'interacaoPedidos', pedido.id), {
      reacoes: arrayUnion(uidAtual),
      [`reacoesEmoji.${uidAtual}`]: emoji,
    });
  }

  async function publicarVersiculo() {
    if (!uidAtual) {
      Alert.alert('Atenção', 'Entre na sua conta para participar.');
      return;
    }

    const texto = novoVersiculo.trim();
    const referencia = novaReferencia.trim();
    if (!texto || !referencia) {
      Alert.alert('Versículo Dia', 'Preencha o versículo e a referência.');
      return;
    }

    await addDoc(collection(firestore, 'interacaoVersiculos'), {
      texto,
      referencia,
      autorUid: uidAtual,
      autorNome: nomeAtual,
      criadoEm: serverTimestamp(),
    });
    await adicionarPontos(uidAtual, nomeAtual, PONTOS_VERSICULO);
    animarMoedinha(PONTOS_VERSICULO);
    setNovoVersiculo('');
    setNovaReferencia('');
  }

  async function responderQuiz(opcao: string) {
    if (!uidAtual) {
      Alert.alert('Atenção', 'Entre na sua conta para participar.');
      return;
    }

    if (opcao !== quizAtual.resposta) {
      animarFeedbackQuiz('erro');
      return;
    }

    const acertoRef = doc(firestore, 'interacaoQuizAcertos', `${quizAtual.id}_${uidAtual}`);
    const acertoSnap = await getDoc(acertoRef);
    if (acertoSnap.exists()) {
      Alert.alert('Quiz Bíblico', 'Você já pontuou nesta pergunta.');
      return;
    }

    await setDoc(acertoRef, {
      quizId: quizAtual.id,
      uid: uidAtual,
      nome: nomeAtual,
      criadoEm: serverTimestamp(),
    });
    await adicionarPontos(uidAtual, nomeAtual, PONTOS_QUIZ);
    animarMoedinha(PONTOS_QUIZ);
    animarFeedbackQuiz('acerto');
  }

  const participantes = React.useMemo(() => (
    NOMES_USUARIOS
      .map(nome => {
        const uid = Object.keys(UID_TO_NOME).find(uidUsuario => UID_TO_NOME[uidUsuario] === nome);
        const pontosPorUid = uid ? Number(pontos[uid] || 0) : 0;
        const pontosPorNome = Number(pontos[nome] || 0);

        return {
          nome,
          foto: fotosUsuarios[nome] || FOTOS_PADRAO[nome],
          pontos: pontosPorUid + pontosPorNome,
        };
      })
      .sort((a, b) => b.pontos - a.pontos || a.nome.localeCompare(b.nome))
  ), [fotosUsuarios, pontos]);

  const iconScale = iconPulse.interpolate({
    inputRange: [0, 1],
    outputRange: [1, 1.08],
  });
  const iconFloat = iconPulse.interpolate({
    inputRange: [0, 1],
    outputRange: [0, -3],
  });

  const renderOracao = () => (
    <View style={styles.section}>
      <View style={styles.inputBox}>
        <View style={styles.cardLight} />
        <TextInput
          style={styles.input}
          value={novoPedido}
          onChangeText={setNovoPedido}
          placeholder="Escreva um pedido de oração"
          placeholderTextColor="#91A4BF"
          multiline
        />
        <TouchableOpacity style={styles.primaryButton} onPress={publicarPedido} activeOpacity={0.85}>
          <LinearGradient colors={['#67E8F9', '#2DD4BF']} style={styles.primaryButtonGradient}>
            <Text style={styles.primaryButtonText}>Publicar</Text>
          </LinearGradient>
        </TouchableOpacity>
      </View>
      <FlatList
        data={pedidos}
        keyExtractor={item => item.id}
        contentContainerStyle={styles.listContent}
        renderItem={({ item }) => (
          <View style={styles.prayerCard}>
            <View style={styles.cardLight} />
            <Text style={styles.prayerAuthor}>{item.autorNome}</Text>
            <Text style={styles.prayerText}>{item.texto}</Text>
            <View style={styles.emojiRow}>
              {EMOJIS_ORACAO.map(emoji => {
                const reacoes = Object.values(item.reacoesEmoji || {});
                const quantidade = reacoes.filter(reacao => reacao === emoji).length;
                const selecionado = item.reacoesEmoji?.[uidAtual] === emoji;

                return (
                  <TouchableOpacity
                    key={emoji}
                    style={[styles.emojiButton, selecionado && styles.emojiButtonSelected]}
                    onPress={() => reagirPedido(item, emoji)}
                    activeOpacity={0.85}
                  >
                    <Text style={styles.emojiText}>{emoji}</Text>
                    <Text style={[styles.emojiCount, selecionado && styles.emojiCountSelected]}>{quantidade}</Text>
                  </TouchableOpacity>
                );
              })}
            </View>
          </View>
        )}
      />
    </View>
  );

  const renderQuiz = () => (
    <ScrollView contentContainerStyle={styles.sectionScroll}>
      <Animated.View style={[styles.iconWrap, styles.iconWrapQuiz, { transform: [{ translateY: iconFloat }, { scale: iconScale }] }]}>
        <View style={styles.iconLight} />
        <MaterialCommunityIcons name="help-circle" size={42} color="#08101F" />
      </Animated.View>
      <Text style={styles.heading}>Quiz Bíblico</Text>
      <Text style={styles.description}>Um quiz novo a cada 7 dias. Acertou, ganhou +{PONTOS_QUIZ} pontos para o Soma.</Text>
      <View style={styles.quizBox}>
        <View style={styles.cardLight} />
        <Text style={styles.quizQuestion}>{quizAtual.pergunta}</Text>
        {quizAtual.opcoes.map(opcao => (
          <TouchableOpacity key={opcao} style={styles.optionButton} onPress={() => responderQuiz(opcao)} activeOpacity={0.85}>
            <LinearGradient colors={['rgba(103,232,249,0.22)', 'rgba(45,212,191,0.12)']} style={styles.optionButtonGradient}>
              <Text style={styles.optionText}>{opcao}</Text>
            </LinearGradient>
          </TouchableOpacity>
        ))}
      </View>
    </ScrollView>
  );

  const renderVersiculo = () => (
    <View style={styles.section}>
      <View style={styles.inputBox}>
        <View style={styles.cardLight} />
        <TextInput
          style={styles.input}
          value={novoVersiculo}
          onChangeText={setNovoVersiculo}
          placeholder="Digite o versículo do dia"
          placeholderTextColor="#91A4BF"
          multiline
        />
        <TextInput
          style={styles.referenceInput}
          value={novaReferencia}
          onChangeText={setNovaReferencia}
          placeholder="Referência. Ex: Salmos 96:1"
          placeholderTextColor="#91A4BF"
        />
        <TouchableOpacity style={styles.primaryButton} onPress={publicarVersiculo} activeOpacity={0.85}>
          <LinearGradient colors={['#FFD166', '#67E8F9']} style={styles.primaryButtonGradient}>
            <Text style={styles.primaryButtonText}>Publicar versículo</Text>
          </LinearGradient>
        </TouchableOpacity>
      </View>
      <FlatList
        data={versiculos}
        keyExtractor={item => item.id}
        contentContainerStyle={styles.listContent}
        renderItem={({ item }) => (
          <View style={styles.verseCard}>
            <View style={styles.cardLight} />
            <Animated.View style={[styles.verseIcon, { transform: [{ scale: iconScale }] }]}>
              <MaterialCommunityIcons name="book-cross" size={20} color="#08101F" />
            </Animated.View>
            <View style={styles.verseContent}>
              <Text style={styles.verseText}>{item.texto}</Text>
              <Text style={styles.verseReference}>{item.referencia}</Text>
              <Text style={styles.verseAuthor}>Publicado por {item.autorNome}</Text>
            </View>
          </View>
        )}
      />
    </View>
  );

  const renderSoma = () => (
    <View style={styles.section}>
      <FlatList
        data={participantes}
        keyExtractor={item => item.nome}
        contentContainerStyle={styles.listContent}
        renderItem={({ item, index }) => (
          <View style={styles.participantCard}>
            <View style={styles.cardLight} />
            <Text style={styles.position}>{index + 1}</Text>
            <LinearGradient
              colors={item.pontos > 0 ? ['#FFF4BF', '#F59E0B', '#B45309'] : ['#67E8F9', '#38BDF8', '#2563EB']}
              style={styles.avatarRing}
            >
              <Image source={{ uri: item.foto }} style={styles.avatar} />
            </LinearGradient>
            <Text style={styles.participantName}>{item.nome}</Text>
            <View style={styles.pointsBadge}>
              <Text style={styles.pointsText}>{item.pontos} pts</Text>
            </View>
          </View>
        )}
      />
    </View>
  );

  const renderConteudo = () => {
    if (abaAtiva === 'quiz') return renderQuiz();
    if (abaAtiva === 'versiculo') return renderVersiculo();
    if (abaAtiva === 'soma') return renderSoma();
    return renderOracao();
  };

  const renderTutorial = () => (
    <Modal
      animationType="fade"
      transparent
      visible={tutorialVisivel}
      onRequestClose={() => setTutorialVisivel(false)}
    >
      <View style={styles.modalOverlay}>
        <View style={styles.tutorialCard}>
          <LinearGradient
            colors={['rgba(103,232,249,0.24)', 'rgba(255,209,102,0.12)', 'rgba(255,255,255,0.06)']}
            start={{ x: 0, y: 0 }}
            end={{ x: 1, y: 1 }}
            style={styles.tutorialGradient}
          >
            <View style={styles.tutorialHeader}>
              <View>
                <Text style={styles.tutorialEyebrow}>Guia rápido</Text>
                <Text style={styles.tutorialTitle}>Como usar as interações</Text>
              </View>
              <TouchableOpacity
                style={styles.tutorialCloseButton}
                onPress={() => setTutorialVisivel(false)}
                activeOpacity={0.85}
              >
                <Feather name="x" size={20} color="#F8FBFF" />
              </TouchableOpacity>
            </View>

            <ScrollView contentContainerStyle={styles.tutorialScroll}>
              {TUTORIAL_INTERACOES.map(item => (
                <View key={item.titulo} style={styles.tutorialSection}>
                  <View style={styles.tutorialSectionHeader}>
                    <View style={[styles.tutorialIcon, { backgroundColor: item.cor }]}>
                      <MaterialCommunityIcons name={item.icone} size={19} color="#08101F" />
                    </View>
                    <Text style={styles.tutorialSectionTitle}>{item.titulo}</Text>
                  </View>
                  {item.instrucoes.map(instrucao => (
                    <View key={instrucao} style={styles.tutorialStep}>
                      <View style={styles.tutorialBullet} />
                      <Text style={styles.tutorialStepText}>{instrucao}</Text>
                    </View>
                  ))}
                </View>
              ))}
            </ScrollView>
          </LinearGradient>
        </View>
      </View>
    </Modal>
  );

  return (
    <LinearGradient colors={['#102B52', '#071B3D', '#050A24']} style={styles.fundo}>
      <SafeAreaView style={styles.container}>
        {renderTutorial()}
        <Animated.View
          pointerEvents="none"
          style={[
            styles.coinToast,
            {
              opacity: moedaAnim.interpolate({
                inputRange: [0, 0.25, 1.5, 2],
                outputRange: [0, 1, 1, 0],
              }),
              transform: [
                {
                  translateY: moedaAnim.interpolate({
                    inputRange: [0, 1, 2],
                    outputRange: [24, -8, -46],
                  }),
                },
                {
                  scale: moedaAnim.interpolate({
                    inputRange: [0, 0.35, 1, 2],
                    outputRange: [0.7, 1.12, 1, 0.86],
                  }),
                },
              ],
            },
          ]}
        >
          <View style={styles.coinCircle}>
            <Text style={styles.coinSymbol}>S</Text>
          </View>
          <Text style={styles.coinText}>+{pontosAnimados}</Text>
        </Animated.View>

        {feedbackQuiz && (
          <Animated.View
            pointerEvents="none"
            style={[
              styles.quizFeedback,
              feedbackQuiz === 'acerto' ? styles.quizFeedbackSuccess : styles.quizFeedbackError,
              {
                opacity: feedbackAnim.interpolate({
                  inputRange: [0, 0.2, 1.5, 2],
                  outputRange: [0, 1, 1, 0],
                }),
                transform: [
                  {
                    translateY: feedbackAnim.interpolate({
                      inputRange: [0, 1, 2],
                      outputRange: [14, -8, -36],
                    }),
                  },
                  {
                    scale: feedbackAnim.interpolate({
                      inputRange: [0, 0.35, 1, 2],
                      outputRange: [0.84, 1.08, 1, 0.92],
                    }),
                  },
                ],
              },
            ]}
          >
            <MaterialCommunityIcons
              name={feedbackQuiz === 'acerto' ? 'check-circle' : 'close-circle'}
              size={22}
              color={feedbackQuiz === 'acerto' ? '#08101F' : '#FFFFFF'}
            />
            <Text style={[styles.quizFeedbackText, feedbackQuiz === 'erro' && styles.quizFeedbackTextError]}>
              {feedbackQuiz === 'acerto' ? 'Você acertou!' : 'Você errou!'}
            </Text>
          </Animated.View>
        )}

        <View style={styles.header}>
          <TouchableOpacity style={styles.headerButton} onPress={() => navigation.navigate('Inicio' as never)} activeOpacity={0.85}>
            <Feather name="arrow-left" size={20} color="#F8FBFF" />
          </TouchableOpacity>
          <Text style={styles.title}>Interação</Text>
          <TouchableOpacity style={styles.helpButton} onPress={() => setTutorialVisivel(true)} activeOpacity={0.86}>
            <LinearGradient
              colors={['#67E8F9', '#2DD4BF']}
              start={{ x: 0, y: 0 }}
              end={{ x: 1, y: 1 }}
              style={styles.helpButtonGradient}
            >
              <Feather name="help-circle" size={21} color="#08101F" />
            </LinearGradient>
          </TouchableOpacity>
        </View>

        <View style={styles.tabs}>
          {ABAS.map(aba => {
            const ativa = aba.id === abaAtiva;
            return (
              <TouchableOpacity key={aba.id} style={[styles.tabButton, ativa && styles.tabButtonActive]} onPress={() => setAbaAtiva(aba.id)} activeOpacity={0.86}>
                <LinearGradient
                  colors={ativa ? ['#67E8F9', '#2DD4BF'] : ['#243A5C', '#182B49']}
                  start={{ x: 0, y: 0 }}
                  end={{ x: 1, y: 1 }}
                  style={styles.tabGradient}
                >
                  <Animated.View style={{ transform: [{ translateY: iconFloat }, { scale: ativa ? iconScale : 1 }] }}>
                    <MaterialCommunityIcons name={aba.icone} size={18} color={ativa ? '#08101F' : aba.corIcone} />
                  </Animated.View>
                  <Text style={[styles.tabText, ativa && styles.tabTextActive]} numberOfLines={2} adjustsFontSizeToFit>{aba.titulo}</Text>
                </LinearGradient>
              </TouchableOpacity>
            );
          })}
        </View>

        {renderConteudo()}
      </SafeAreaView>
    </LinearGradient>
  );
}

